"""ReconnectStrategy — 指数退避断线重连策略。

参考 gRPC 的 backoff 策略：
- 基础延迟 + 随机抖动（jitter）避免雷群效应
- 指数增长直到上限
- 连接成功后重置
"""
import logging
import random
import time

logger = logging.getLogger("agent.ws.reconnect")


class ReconnectStrategy:
    """指数退避重连策略。

    参数:
        base_delay:  初始等待秒数（默认 1s）
        max_delay:   最大等待秒数（默认 60s）
        multiplier:  退避倍数（默认 2.0）
        jitter:      随机抖动比例（默认 0.1，即 ±10%）
    """

    def __init__(self, base_delay=1.0, max_delay=60.0,
                 multiplier=2.0, jitter=0.1):
        self.base_delay = base_delay
        self.max_delay = max_delay
        self.multiplier = multiplier
        self.jitter = jitter
        self._attempt = 0
        self._current_delay = base_delay

    @property
    def attempt(self):
        return self._attempt

    def next_delay(self):
        """计算下一次重连等待秒数（含抖动）。"""
        delay = self._current_delay
        # 添加随机抖动
        if self.jitter > 0:
            jitter_range = delay * self.jitter
            delay += random.uniform(-jitter_range, jitter_range)
        delay = max(0, delay)

        # 更新下次延迟
        self._current_delay = min(
            self._current_delay * self.multiplier, self.max_delay)
        self._attempt += 1

        logger.info('重连等待 %.1fs（第 %d 次）', delay, self._attempt)
        return delay

    def wait(self):
        """同步等待下一次重连。"""
        delay = self.next_delay()
        time.sleep(delay)
        return delay

    async def async_wait(self):
        """异步等待下一次重连。"""
        import asyncio
        delay = self.next_delay()
        await asyncio.sleep(delay)
        return delay

    def reset(self):
        """连接成功后调用，重置退避状态。"""
        if self._attempt > 0:
            logger.info('连接已恢复（曾重试 %d 次），重置退避',
                        self._attempt)
        self._attempt = 0
        self._current_delay = self.base_delay
